var MEDIA_REPLACEMENT_POINTS = {"TV":{"Micro RGB":["[디스플레이 세대교체] 백라이트나 컬러 필터의 열화로 점차 색이 바래가는 구형 TV는 이제 그만. 픽셀 자체가 스스로 빛과 순색을 발산하여 평생 변치 않는 화질을 제공하는 차세대 기술로 갈아탈 때입니다.","구독 기간 내 패널 걱정 없는 무상 A/S 및 이사 시 전문가가 안전하게 이전해 주는 무상 재설치 1회 기본 제공"],"Mini LED":["[로컬디밍 명암비의 혁신] 화면 전체를 한 번에 밝혀 어두운 장면이 뿌옇게 뜨던 오래된 일반 LED TV의 한계를 극복했습니다. 머리카락 한 올 크기의 초소형 미니 LED 백라이트가 촘촘하게 빛을 제어해 정밀하고 리얼한 블랙을 표현합니다.","비싼 하이엔드 화질의 장벽을 낮춘 실리적 구독료 및 무상 A/S 제공"],"Neo QLED":["[저화질 소스의 심폐소생] 예전 해상도로 제작된 뉴스나 예능을 볼 때 답답하셨다면, Neo QLED AI 프로세서가 선명하고 부드러운 화질로 실시간 업스케일링하여 구형 콘텐츠도 완전히 새롭게 바꿔줍니다.","고화질 업그레이드 체감 및 이전 설치 걱정을 덜어주는 무상 재설치 1회 지원"],"OLED":["[반사 및 명암비 해방] 형광등 빛이나 대낮 창문 비침 때문에 인상을 찌푸리며 시청하던 구형 TV에서 벗어나세요. 글레어 프리 기술과 무한대 명암비로 눈 피로 없이 깊은 몰입감을 선사합니다.","눈 피로 감소 소구 및 패널 수명 걱정을 덜어주는 무상 A/S & 무상 재설치 1회 지원"],"The Movingstyle":["[시청 패러다임의 교체] 안방, 주방, 거실 등 공간마다 TV를 여러 대 살 필요가 없습니다. 가구 위치에 맞춰, 혹은 내가 이동하는 동선에 맞춰 가볍게 굴려 움직이는 프리미엄 홈 스크린으로 라이프스타일을 교체하세요.","[방문 케어 옵션 선택 시] 내가 직접 청소하고 관리할 필요 없이 전문가가 알아서 클리닝해 주는 무빙 전용 케어 서비스 제공"],"무빙스타일":["[고정형에서 이동형으로] 거실 벽에만 덩그러니 붙어있던 구형 TV를 치우고, 집안 어디든 쓱 밀고 다니며 다용도로 쓸 수 있는 실용적이고 세련된 이동형 TV로 가볍게 시작해 보세요.","가벼운 구독 부담 및 기기 고장 고민을 해결해 주는 무상 A/S 보장"],"The Frame":["[두꺼운 검은 베젤 탈출] 거실 인테리어를 해치던 투박하고 두꺼운 구형 TV 대신, 벽면에 완전히 밀착되며 원하는 그림/액자 프레임으로 갈아 끼울 수 있는 액자형 TV로 감각적인 인테리어를 완성하세요.","집안 분위기 혁신 및 구독형 소유로 목돈 부담 완화 (무상 A/S)"],"The Serif":["[TV 장식장 철거] 공간만 넓게 차지하고 청소하기 힘들었던 오래된 TV 장식장은 버리세요. 독보적인 'I'자형 디자인으로 장식장 없이 공간 어디든 무심하게 세워두기만 해도 감성적인 인테리어가 됩니다.","미니멀 가구 배치 유도 및 안심 유지보수 (무상 A/S)"],"Crystal UHD":["[가성비 극대화 교체] 구형 TV가 고장 났을 때 청구되는 비싼 패널 수리비나 부품 교체 비용 부담을 단번에 날려버리세요. 커피 몇 잔 값의 월 구독료로 언제나 안심하고 쓸 수 있는 실속형 최신 4K TV로 교체하는 것이 훨씬 똑똑한 소비입니다.","노후 기기 수리비 대비 월 구독 경제성 강조, 폐가전 무상 수거 및 무상 A/S 기본 보장"]},"모니터":{"스마트 모니터":["[본체 없는 미니멀리즘] 부팅도 느리고 자리만 차지하는 구형 PC 본체와 얽힌 선들을 모두 정리하세요. 모니터 하나만 켜면 넷플릭스 등 OTT는 물론 문서 작업, 화상 회의까지 무선으로 한 번에 처리해 주는 스마트 홈오피스로 바뀝니다.","PC 본체 유지비용 절감 소구 및 안심 사용 (무상 A/S)"],"무빙스타일 모니터":["[책상 위 해방] 책상 한가운데 고정되어 공간만 좁게 만들던 구형 컴퓨터 모니터에서 벗어나세요. 바퀴가 달린 세련된 무빙 스탠드 형태로, 필요할 때만 침대나 소파 옆으로 끌어와 편안한 자세로 멀티태스킹을 즐길 수 있습니다.","공간 효율 극대화, [방문 케어 옵션 선택 시] 정기 패널 클리닝으로 언제나 최상의 화면 컨디션 유지"],"게이밍 모니터":["[주사율 스펙 점프업] 주사율이 낮아 툭툭 끊기고 화면 잔상이 남던 구형 일반 모니터는 고사양 게임의 적입니다. 240Hz 이상의 초고주사율과 압도적인 응답속도로 장비 탓 없는 승리의 쾌감을 느껴보세요.","장비 노후화로 인한 하드웨어 불만을 해소하고, 고가 장비 감가상각 걱정 없는 구독(무상 A/S) 제안"],"뷰피니티":["[정확한 색상 복원] 백라이트 노후화로 인해 색이 누렇게 뜨거나 물 빠진 듯 틀어지기 시작한 작업용 모니터를 바꾸세요. 팬톤 검증을 통과한 정확한 색 표현력과 5K 고해상도로 원본 그대로의 선명함을 되찾을 수 있습니다.","전문 그래픽/영상 작업을 위한 장비 교체 주기 최적화 및 초기 투자 비용 부담 최소화 (무상 A/S)"]},"오디오":{"Q사운드바":["[홈시어터 선 정리] 거실 바닥과 벽면을 복잡하게 어지럽히던 구형 5.1채널 홈시어터의 수많은 선과 위성 스피커를 싹 치우세요. TV 아래에 슬림하게 밀착되는 바 하나와 무선 서브우퍼만으로 복잡함 없이 더 웅장한 입체 음향을 완성합니다.","TV 구독 결합 시 할인 혜택 극대화 및 미니멀 인테리어 완성 (무상 A/S)"],"뮤직스튜디오7":["[사운드 출력 업그레이드] 소리가 뭉개지고 찢어지는 구형 스피커를 버리고, 하이엔드 다채널 입체 사운드 시스템으로 음악과 영화의 미세한 사운드 결까지 풍성하게 체감해 보세요.","프리미엄 음향 교체 갈증 해결 및 기기 안심 유지 (무상 A/S)"],"뮤직스튜디오5":["[블루투스 끊김 해결] 스마트폰과 연결할 때마다 툭툭 끊기고 페어링이 복잡하던 오래된 소형 블루투스 스피커는 안녕. 와이파이 기반의 끊김 없는 고음질 전송과 공간 전체를 채우는 360도 무지향 사운드로 공간의 질을 높여줍니다.","오디오 기기 노후화 교체 및 세련된 거실 오브제 효과 강조 (무상 A/S)"],"뮤직프레임":["[신개념 스피커 경험] 공간만 좁게 만들던 뻔한 원통형/박스형 검은색 스피커 대신, 나만의 취향이 담긴 포스터나 사진을 끼워 액자처럼 벽에 걸어둘 수 있는 완전히 새로운 형태의 액자형 와이파이 스피커로 홈 오디오 환경을 교체해 보세요.","감성 라이프스타일로의 인테리어 및 음향 동시 세대교체 소구 (무상 A/S)"]}};
